def rows_of(ws,first,ncol): return [[ws.cell(r,c).value for c in range(1,ncol+1)] for r in range(first,ws.max_row+1) if any(ws.cell(r,c).value is not None for c in (1,2))]
def put(ws,first,rows,ncol,hdr,fix=None):
    st=[copy.copy(ws.cell(first,c)._style) for c in range(1,ncol+1)]
    for k,v in enumerate(rows):
        r=first+k
        if fix: fix(v,r)
        for c in range(1,ncol+1): ws.cell(r,c).value=v[c-1] if c-1<len(v) else None; ws.cell(r,c)._style=copy.copy(st[c-1])
        ws.row_dimensions[r].height=None
    ws.auto_filter.ref=f'A{hdr}:{L(ncol)}{first+len(rows)-1}'
def idx(rows,key,col=0): return next(i for i,r in enumerate(rows) if r[col]==key)
def setc(rows,key,col,val,kc=0): rows[idx(rows,key,kc)][col]=val

