ws=wb['Ziele']; rows=rows_of(ws,5,4)
setc(rows,'Z-04',2,'Zielfahren: Das Ziel ist ein realer Ort, je nach Stufe rund 2 bis 3 km (einfach), 5 km (mittel) oder 10 km (schwer) entfernt. Es soll nicht nur in gerader Linie erreichbar sein, sondern das Ausnutzen von Winden verschiedener Höhen und Richtungen verlangen. Sensible Infrastruktur (Krankenhaus, Flughafen und Ähnliches) ist als Ziel ausgeschlossen.',1); setc(rows,'Z-04',3,'Brainstorm; '+N,1)
