def a(key,**kw):
    m={'C':2,'D':3,'E':4,'F':5,'G':6,'H':7}; r=rows[idx(rows,key)]
    for k,v in kw.items(): r[m[k]]=v
a('SPI-08',C='Hauptmenü im Stil der App',D='Vor der Spiellogik erscheint ein Hauptmenü im Stil der eigentlichen App (gleiche Farben, Schriften und Flächen), damit es keine Erwartung an ein Retro-Spiel der 80er weckt. Es erscheint nach einer Sekunde und wird weich eingeblendet. Dahinter läuft ein ruhig bewegtes Bild in den Farben der App: ein Ballon von der Seite, der unten links am Boden beginnt, Sand abwirft, steigt und wieder sinkt. Im Menü gibt der Spieler seinen Namen ein. Zur Auswahl stehen Freie Fahrt, Challenge, Bestenliste, Wettkampf und Meisterschaft.',E='Das Menü sieht aus wie die übrigen Fenster der App und erscheint nach einer Sekunde; alle fünf Punkte sind zu sehen, Wettkampf und Meisterschaft gesperrt.',H=N+'; ersetzt den Stil der Heimcomputer der 80er; Bild und Musik siehe OP-37')
a('SPI-10',C='Challenge mit Untermenü der Aufgaben',D='Unter Challenge öffnet sich ein Untermenü mit den Aufgaben Zielfahren, Wandziel, Max. Distanz (MDT) und Min. Distanz (MID). Jede Aufgabe hat eine kurze Beschreibung, eine eigene Vorbereitung und ein eigenes Startfenster.',E='Alle vier Aufgaben lassen sich aus dem Untermenü starten und enden mit Punkten.',G='Umgesetzt',H=N+'; weitere Aufgaben siehe OP-26')
a('STE-08',D='Die Statusanzeige zeigt die Höhe über Grund groß und darunter grau die Höhe NN, das Steigen und Sinken, Fahrtrichtung und Geschwindigkeit, Zeit, Weg, den Sand, den Füllgrad des Traggases in Prozent mit einer Nachkommastelle und die Entfernung zum Ziel (im Wandziel zum nächsten Target Cross, bei MDT und MID zum Startplatz). Der Wind in der Höhe des Ballons ist im Vertikalprofil abzulesen.',H='Vorlage in der Tracker-App: CHS-06; '+N)
a('TON-01',D=rows[idx(rows,'TON-01')][3].replace('Im Hauptmenü läuft eine frei erfundene Musik im Klang der Heimcomputer der 80er; sie lässt sich getrennt abschalten.','Im Hauptmenü läuft eine frei erfundene Musik im Klang der Heimcomputer der 80er; sie setzt nach dem Einblenden des Menüs deutlich hörbar ein, wird nach einigen Takten leiser und lässt sich getrennt abschalten.')+' Der Abwurf eines Säckchens hat einen eigenen Ton.',H=N+'; Startmelodie war am Handy nicht zu hören, siehe OP-38')
a('ZIE-01',C='Reales Ziel in fester Entfernung je Stufe',D='Zu Beginn jeder Runde im Zielfahren wählt die App ein reales Ziel. Auf der Stufe einfach liegt es 2 bis 3 km entfernt, auf mittel rund 5 km, auf schwer rund 10 km.',E='Das Ziel liegt auf einfach 2 bis 3 km, auf mittel 4 bis 6 km, auf schwer 8 bis 12 km vom Start; mehrere Runden ergeben unterschiedliche Ziele.',G='Umgesetzt',H=N+'; vorher nach Fahrzeit; bei sehr starkem Wind liegt das Ziel so nah am Bereich wie möglich')
a('ZIE-04',D='Zum gerechneten Landepunkt sucht die App einen Sportplatz aus OpenStreetMap (öffentlicher Overpass-Dienst) im Umkreis von 15 Prozent der Zielentfernung, mindestens 250 m und höchstens 1,2 km, und macht den nächsten geeigneten zum Ziel, mit seinem Namen. Gibt es keinen, markiert sie eine Landezone am gerechneten Punkt. Antwortet der Kartendienst nicht, bleibt es bei der Landezone, und das Startfenster sagt, dass sie nicht auf Gewässer und gesperrte Orte geprüft wurde.',H=N+'; Verkehrsinseln und weitere Zieltypen siehe OP-04')
a('PUN-02',D='Die volle Punktzahl im Zielfahren gibt es nur bei sanfter Landung. Vorläufig: bis 1,0 m/s kein Abzug, darüber linear bis zur halben Punktzahl bei 2,9 m/s und mehr (Bruchlandung, PUN-08).')
a('PUN-06',G='Teilweise',H='Nutzer 07.10.2026 (Version 0.3); in der Bestenliste des Geräts umgesetzt, für die gemeinsame Liste braucht es den Online-Dienst (SRV-02)')
a('PUN-07',D='Der Spieler gibt im Hauptmenü seinen Namen ein. Die Bestenliste ist ein eigener Menüpunkt und zeigt die Werte aller gefahrenen Wettbewerbe mit den Spalten Rang, Name, Punkte und Challenge; beim Zielfahren steht die Stufe dabei. Bei gleicher Punktzahl liegt vorn, wer mehr Sand übrig hat. Die Liste reicht bis Rang 100 und lässt sich scrollen. Solange kein Server angebunden ist, liegt sie auf dem Gerät.',E='Nach jeder gewerteten Fahrt steht der Eintrag mit Rang, Name, Punkten und Challenge in der Liste; die Auswertung nennt den Platz.',H=N+'; gemeinsame Liste für alle Nutzer siehe SRV-02')
a('MET-06',D='Vor der Runde lässt sich wählen, ob mit den realen Wetterdaten des Startorts oder mit einer simulierten Atmosphäre gespielt wird. In der Simulation kommt der Wind nach jedem Start aus einer anderen Richtung und dreht mit der Höhe in unregelmäßigen Abständen; Bodenwerte und Inversion sind ebenfalls zufällig.',E='Beide Arten lassen sich wählen; mehrere Starts in der Simulation zeigen unterschiedliche Windrichtungen.',H=N+'; OP-18 geschlossen')
a('MET-08',D='Das Startfenster nennt, woher das geladene Wettermodell stammt: die Quelle, den Stand und den Gitterpunkt des Modells mit Ortsnamen, Himmelsrichtung und Entfernung vom Startplatz, immer in km mit einer Nachkommastelle.',E='Im Startfenster stehen Ortsname, Himmelsrichtung und Entfernung in km; ohne Ortsnamen bleiben Richtung und Entfernung.',H=N+'; Ortsname aus OpenStreetMap (Nominatim), kommt im Hintergrund nach')
a('DAT-02',C='Speicherung auf dem Gerät',D='Einstellungen, Zwischenspeicher und Ergebnisse bleiben auf dem Handy, solange kein Online-Dienst angebunden ist. Mit Online-Dienst gehen die gewerteten Fahrten (Name, Punkte, Aufgabe) und die Angaben für die Zugriffsstatistik an den Server (SRV-02 bis SRV-05); der Standort wird nicht übertragen.',E='Ohne eingetragenen Dienst gehen keine Daten an einen eigenen Server.',H='Vorschlag; '+N)
B='Aufgaben'
i=idx(rows,'ZIE-07')+1
rows[i:i]=[
 ['AUF-01',B,'Fester Startplatz für Wandziel, MDT und MID','Die Aufgaben Wandziel, MDT und MID starten immer am Ballonstartplatz Bitterfeld; der Startplatz ist dort nicht wählbar. Der vom Spieler gewählte Startplatz für Freie Fahrt und Zielfahren bleibt erhalten.','In diesen drei Aufgaben fehlt die Startplatzwahl und der Ballon steht in Bitterfeld; danach gilt in der freien Fahrt wieder der gewählte Startplatz.','Muss','Umgesetzt',N+'; welches Wetter dort gilt, siehe OP-40',None],
 ['AUF-02',B,'Wandziel: Target Cross','Je nach Windmodell werden 2 bis 3 Target Cross gesetzt, 100 m bis 2 km voneinander entfernt. Ein Target Cross ist 6 m breit, jeder Strich 1 m breit. Die Kreuze liegen so, dass sie mit dem Wind des Tages nacheinander erreichbar sind; auf der Karte sind sie zusätzlich mit einem Zeichen, ihrer Nummer und ihrem Wertungsradius markiert.','Zwei oder drei Kreuze erscheinen; ihre Abstände liegen zwischen 100 m und 2 km; in der Karte ist das Kreuz 6 m breit.','Muss','Umgesetzt',N+'; drei Kreuze bei mindestens 12° Richtungsunterschied in den unteren Schichten (Festlegung Claude); Name der Aufgabe siehe OP-31',None],
 ['AUF-03',B,'Wandziel: Säckchen abwerfen','An Bord sind so viele farbige Säckchen wie Target Cross. Ein Säckchen wiegt 70 g. Abgeworfen wird über einen eigenen Knopf rechts unten, der auch die Zahl der übrigen Säckchen zeigt. Das Säckchen fällt und treibt dabei mit dem Wind; sein Auftreffpunkt wird auf der Karte markiert und der Abstand zum Kreuz gemeldet. Die Fahrt endet mit der Landung; wo gelandet wird, ist egal.','Der Knopf zeigt die Zahl der Säckchen; jeder Abwurf verringert sie um eins und macht den Ballon um 70 g leichter; nach der Landung erscheint die Auswertung.','Muss','Umgesetzt',N+'; Fall mit 9 m/s ist Annahme Claude (OP-31)',None],
 ['AUF-04',B,'Wandziel: Wertung','Je Target Cross zählt das nächstgelegene Säckchen: 100 Punkte auf dem Kreuz (bis 3 m), linear fallend auf 0 in 100 m Abstand. Die Punktzahl der Fahrt ist der Mittelwert über alle Kreuze. Ein Säckchen darf überall abgeworfen werden; gewertet wird es am nächstgelegenen Kreuz. Die Landung selbst gibt keinen Abzug.','Ein Säckchen 9 m neben einem Kreuz bringt 94 Punkte für dieses Kreuz; ein Kreuz ohne Säckchen zählt 0.','Muss','Umgesetzt','Vorschlag Claude, vom Nutzer nicht vorgegeben; zu bestätigen (OP-31)',None],
 ['AUF-05',B,'MDT: möglichst weit in fester Zeit','Bei Max Distance (MDT) muss in einer festen Zeit möglichst weit gefahren werden. Die Zeit soll später zwischen 3 und 5 Stunden wählbar sein, zunächst gelten 3 Stunden. Unten rechts läuft eine Zeitanzeige im Format HH:MM:SS; sie zeigt die Restzeit und danach die Überzeit. Die Fahrt endet mit der Landung.','Die Zeitanzeige läuft ab dem Abheben von 03:00:00 herunter und zeigt nach Ablauf die Überzeit in Rot.','Muss','Umgesetzt',N+'; Wahl der Dauer 3 bis 5 Stunden noch offen (OP-32)',None],
 ['AUF-06',B,'MDT: Wertung und Statistik','100 Punkte gibt es, wenn man so weit kommt, wie unter optimalen Bedingungen möglich ist; für weniger Weite anteilig weniger. Für jede Minute über der Zeit gibt es einen Punkt Abzug. Am Ende zeigt eine Statistik: so weit hättest du kommen können, so weit bist du gekommen, so viele Strafpunkte wurden abgezogen. Die bestmögliche Weite wird vor dem Start berechnet und nach der Landung als gestrichelte Linie gezeigt.','Wer 80 Prozent der Bestweite erreicht und gut 3 Minuten zu spät landet, erhält 77 Punkte; die Statistik nennt beide Weiten und die Strafpunkte.','Muss','Umgesetzt',N+'; Bestweite = weiteste Fahrt in gleichbleibender Höhe bis 6000 m mit dem Wetter des Startzeitpunkts (Vorschlag Claude, OP-32)',None],
 ['AUF-07',B,'MID: möglichst wenig Strecke in einer Stunde','Bei Min Distance (MID) soll eine Stunde gefahren und dabei möglichst wenig Strecke zurückgelegt werden; die Fahrt endet mit der Landung. 100 Punkte gibt es bei Landung innerhalb von 200 m um den Startplatz; je weitere 200 m gibt es einen Punkt Abzug. Wird früher oder später als nach einer Stunde gelandet, kostet jede Minute einen Punkt. Eine Zeitanzeige läuft mit; der 200-m-Kreis ist auf der Karte markiert.','Eine Landung 350 m vom Start nach 1:02 Stunden ergibt 97 Punkte.','Muss','Umgesetzt',N+'; gewertet wird die Luftlinie vom Start zum Landeplatz, Abzug je volle Minute (OP-33)',None],
 ['AUF-08',B,'MID: Windmodell mit allen Richtungen','Für MID deckt das Windmodell bis in 6000 m Höhe alle Windrichtungen ab, in unregelmäßigen Abständen. Die Aufgabe läuft deshalb immer mit simuliertem Wetter.','Zwischen Boden und 6000 m kommt jede Windrichtung vor; die Wetterwahl entfällt in dieser Aufgabe.','Muss','Umgesetzt',N,None],
]
i=idx(rows,'PUN-07')+1
rows.insert(i,['PUN-08','Punkte','Rückmeldung zur Landung','Nach der Landung nennt die Auswertung je nach Sinkgeschwindigkeit beim Aufsetzen: 0 bis 0,5 m/s „Butterweiche Landung“; über 0,5 bis 1,5 m/s „Sportlich, sportlich“; über 1,5 bis 2,8 m/s „Das war ne wilde Landung“; ab 2,9 m/s „Bruchlandung – Aua“. Maßgeblich ist der auf eine Nachkommastelle gerundete Wert. Nach einer Bruchlandung bleibt der Jubel aus.','Jede der vier Stufen zeigt ihren Text als Überschrift der Auswertung, in jeder Spielart.','Muss','Umgesetzt',N+'; Verhältnis zum Punktabzug siehe OP-05',None])
a('NFA-03',D='Die Berechnung eines Ziels, der Target Cross oder der Bestweite dauert auf einem Mittelklasse-Handy höchstens 3 Sekunden (Wert zu bestätigen).',H='Vorschlag; am Rechner unter 0,1 s, am Handy nicht gemessen')
rows+=[
 ['NFA-05','Nichtfunktional','Wartezeit bei der Vorbereitung einer Fahrt','Wetter und Gelände werden gleichzeitig geladen; der Ortsname des Wetter-Gitterpunkts kommt im Hintergrund nach. Der Kartendienst für Zielorte bekommt höchstens 7 Sekunden je Abfrage und höchstens zwei Abfragen; seine Antworten werden für die Sitzung gemerkt.','Mit Netz erscheint das Startfenster nach wenigen Sekunden; ohne Antwort des Kartendienstes nach höchstens rund 15 Sekunden.','Soll','Umgesetzt',N+'; Anlass: die Zielsuche dauerte am Handy sehr lange; am echten Dienst noch nicht gemessen',None],
 ['SRV-01','Server','Betrieb auf einem Server','Die App lässt sich auf einen Server hochladen, damit andere Nutzer sie verwenden können. Sie besteht nur aus Dateien mit Pfaden relativ zum eigenen Ordner und braucht eine verschlüsselte Verbindung (HTTPS), damit Installation und Standort funktionieren.','Der Ordner läuft unverändert unter einer anderen Adresse; die App lässt sich von dort installieren.','Muss','Teilweise',N+'; die Dateien enthalten keine festen Adressen des bisherigen Orts; auf einem anderen Server noch nicht ausprobiert (OP-34)',None],
 ['SRV-02','Server','Gemeinsame Bestenliste für alle Nutzer','Die Bestenliste zeigt die Fahrten aller Nutzer, bis Rang 100, zum Scrollen. Dafür meldet die App jede gewertete Fahrt an einen Online-Dienst und holt die Liste dort ab; ist der Dienst nicht erreichbar, zeigt sie die Liste des Geräts und sagt das.','Zwei Geräte sehen dieselbe Liste; sie hat höchstens 100 Zeilen und lässt sich scrollen.','Muss','Teilweise',N+'; App-Seite vorbereitet und abgeschaltet, solange keine Adresse des Dienstes eingetragen ist; der Dienst selbst fehlt (IF-09, OP-34)',None],
 ['SRV-03','Server','Zugriffsstatistik für den Admin','Der Projektinhaber kann als Admin sehen, wie viele unterschiedliche Nutzer auf die App zugegriffen haben und wie lange sie die App nutzen.','Eine nur dem Admin zugängliche Übersicht nennt die Zahl der unterschiedlichen Nutzer und die Nutzungsdauer je Zeitraum.','Soll','Offen',N+'; die App kann Besuch und Nutzungsdauer melden, sobald ein Dienst eingetragen ist; Auswertung und Admin-Zugang fehlen (OP-34, OP-35)',None],
 ['SRV-04','Server','Herkunft der Zugriffe','Wenn möglich zeigt die Statistik, wie die Nutzer zur App gekommen sind: über eine Suchmaschine, einen direkten Link oder besondere QR-Codes. Dafür trägt jeder QR-Code eine eigene Kennung im Link (zum Beispiel ?src=messe).','Die Statistik unterscheidet Zugriffe nach verweisender Seite und nach der Kennung im Link.','Soll','Offen',N+'; die App meldet Kennung und verweisende Seite, sobald ein Dienst eingetragen ist',None],
 ['SRV-05','Server','Datenschutz bei Bestenliste und Statistik','Namen in der gemeinsamen Bestenliste und die Angaben der Zugriffsstatistik können personenbezogen sein. Vor dem Betrieb für andere Nutzer braucht die App einen Datenschutzhinweis und je nach Ausgestaltung eine Einwilligung. Der Standort wird nicht an den Dienst übertragen.','Datenschutzhinweis ist in der App erreichbar; ohne nötige Einwilligung wird keine Gerätekennung gesendet.','Muss','Offen','Vorschlag Claude, keine Rechtsberatung; zu klären (OP-35)',None],
]
